const KEY='woodland-crossings-v1';let storageOK=true,state;
try{state=hydrate(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{state=fresh();storageOK=false;}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let activeCasework=null;
let screen='home',selected=0,feedback=null,solved=false,sound=true,lastResult=null;
try{sound=localStorage.getItem(KEY+'-sound')!=='false';}catch{}
const pageSound=createPageSound();pageSound.setEnabled(sound);
const frogSound=createPageSound({src:'assets/frog-croak.mp3',volume:.24,cooldownMs:400});frogSound.setEnabled(sound);
let audioUnlocked=false;
function unlockAudio(){if(audioUnlocked||!sound)return;audioUnlocked=true;void music.setEnabled(true);}
document.addEventListener?.('pointerdown',unlockAudio,{capture:true});
document.addEventListener?.('keydown',unlockAudio,{capture:true});
const music=createMusicController({onError(){sound=false;pageSound.setEnabled(false);frogSound.setEnabled(false);const b=document.querySelector('#soundBtn');b.textContent='Sound off';b.setAttribute('aria-pressed','false');say('Music could not start. Tap Sound to try again.');}});
document.addEventListener?.('visibilitychange',()=>{const visible=document.visibilityState!=='hidden';music.setVisible(visible);pageSound.setVisible(visible);frogSound.setVisible(visible);});
document.addEventListener?.('click',event=>{if(isPageTurn(event))void pageSound.turn();},true);
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(id,text,cls='primary')=>`<button id="${id}" class="${cls}">${text}</button>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function say(text){document.querySelector('#announce').textContent=text;}
function chime(){if(!sound)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)();[523,659,784].forEach((hz,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.frequency.value=hz;g.gain.setValueAtTime(.035,ac.currentTime+i*.1);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+i*.1+.22);o.start(ac.currentTime+i*.1);o.stop(ac.currentTime+i*.1+.23);});setTimeout(()=>ac.close(),800);}catch{}}
function scene(crossed=false,fitted=false,stage=chapter(state),view=null,frame=null){
 const setting=view||SCENES[stage]||SCENES[0],egg=EGGS[stage%6],found=discoveryList(state.easterEggs).includes(egg.id);
 return `<div class="scene scene-${stage} painted-scene ${setting.indoors?'indoor-scene':'outdoor-scene'} ${crossed||fitted?'fitted':''}" style="--scene-art:url('assets/${setting.asset}');--scene-focus:${setting.focus};--scene-scale:${setting.scale||'100% 100%'}" data-scene-key="${setting.key||stage+'-0'}" data-location="${e(setting.name)}">${landscape(stage)}<div class="moon-mist" aria-hidden="true"></div><div class="forest-sparkles" aria-hidden="true"><i></i><i></i><i></i><i></i></div>${view||setting.asset.startsWith('chapter-one/')?'':`<div class="rabbit ${crossed?'crossed':''}" aria-hidden="true">${rabbitArt(crossed)}</div>`}${crossed?'<div class="found-supply" aria-hidden="true">✦</div>':''}<button class="world-easter egg-${stage} ${found?'found':''}" data-egg="${egg.id}" aria-label="${found?egg.name+' — found':'Inspect the small woodland shape'}" title="${found?egg.name:'Something small is hiding here…'}">${tokenArt(egg.icon)}</button>${frame?frame.frog?frogButton(stage,FROGS.find(f=>f.id===frame.frog.id)?.view||0):'':frogButton(stage,setting.view||0)}</div>`;
}
function bindEasterEggs(root=app){bindFrogs(root);root.querySelectorAll('[data-egg]').forEach(b=>b.onclick=()=>{
 const egg=EGGS.find(x=>x.id===b.dataset.egg);if(!egg)return;
 const before=discoveryList(state.easterEggs);const wasFound=before.includes(egg.id);
 state.easterEggs=discoveryList([...before,egg.id]);save();b.classList.add('found');b.setAttribute('aria-label',egg.name+' — found');
 showModal(`<div class="egg-reveal">${tokenArt(egg.icon)}</div><span class="eyebrow">${wasFound?'A familiar woodland visitor':'A secret in the woods'}</span><h2>${e(egg.name)}</h2><p>${e(egg.text)}</p><p class="small-note">${state.easterEggs.length} / ${EGGS.length} woodland secrets found. Optional discoveries never affect your grammar score.</p>`);
 say(egg.name+' found. '+state.easterEggs.length+' of '+EGGS.length+' woodland secrets.');
 });}
function frogButton(stage,view){const f=frogForScene(stage,view);if(!f)return '';const found=frogFinds(state.frogFinds).includes(f.id);return `<button class="woodland-frog ${found?'found':''}" style="--frog-x:${f.x}%;--frog-y:${f.y}%" data-frog="${f.id}" data-frog-call="true" aria-label="${found?e(f.name)+' — collected':'Inspect a small frog'}" title="${found?e(f.name):'A little woodland visitor'}">${frogArt(f)}</button>`;}
function revealFrog(f){const found=frogFinds(state.frogFinds);const seen=found.includes(f.id);state.frogFinds=frogFinds([...found,f.id]);save();showModal(`<div class="frog-portrait">${frogArt(f)}</div><span class="eyebrow">${seen?'A familiar frog':'A frog for your collection'}</span><h2>${e(f.name)}</h2><p><b>${e(f.topic)}</b></p><p>${e(f.text)}</p><p class="small-note">${state.frogFinds.length} / ${FROGS.length} frogs collected. Reopen their tidbits in Woodland secrets. These visits never affect supplies or grammar scores.</p>`);say(f.name+' collected. '+state.frogFinds.length+' of '+FROGS.length+' frogs.');}
function bindFrogs(root){placeFrogs(root);root.querySelectorAll('[data-frog]').forEach(b=>b.onclick=()=>{const f=FROGS.find(x=>x.id===b.dataset.frog);if(f){if(b.dataset.frogCall==='true')void frogSound.turn();b.classList.add('found');b.setAttribute('aria-label',f.name+' — collected');revealFrog(f);}});}
function frogCollection(){const found=frogFinds(state.frogFinds);return `<h2>The frog fieldbook</h2><p>${found.length} / ${FROGS.length} collected. A small visitor may be hiding in each scene. Every frog has a different word or sentence to share.</p><div class="secret-grid">${FROGS.map(f=>`<div class="secret-item">${found.includes(f.id)?frogArt(f):'<span aria-hidden="true">?</span>'}<small>Chapter ${f.stage+1}</small><p>${found.includes(f.id)?e(f.name):'An undiscovered frog'}</p>${found.includes(f.id)?`<button class="text-button" data-frog="${f.id}">Read tidbit</button>`:''}${frogReached(f,state)?`<button class="text-button" data-frog-search="${f.id}">Look around</button>`:'<small>Keep exploring the story.</small>'}</div>`).join('')}</div>`;}
function evidenceBoard(){const unlocked=unlockedCases(state.story);return `<section class="evidence-board"><div class="section-top"><div><span class="eyebrow">Poppy’s case notes</span><h2>The pieces of the mystery</h2></div><span class="status-pill">${unlocked} / 6 notes uncovered</span></div><div class="evidence-grid">${CASES.map((c,i)=>`<article class="evidence-card ${i<unlocked?'uncovered':'sealed'}">${i<unlocked?tokenArt(c.icon):'<span class="sealed-mark" aria-hidden="true">?</span>'}<span class="eyebrow">${i<unlocked?'NOTE '+(i+1):'SEALED NOTE'}</span><h3>${i<unlocked?e(c.title):'Still hidden in the rain'}</h3><p>${i<unlocked?e(c.clue):'Continue the investigation to uncover this note.'}</p></article>`).join('')}</div></section>`;}
function journal(){const found=discoveryList(state.easterEggs),available=chapter(state)+1;showModal(`<span class="eyebrow">Optional woodland discoveries</span><h2>Small secrets, big ears.</h2><p>Some woodland visitors like to hide. Revisit any location you have reached to look around, without repeating its grammar questions.</p><div class="secret-grid">${EGGS.map((x,i)=>`<div class="secret-item ${found.includes(x.id)?'':'undiscovered'}">${found.includes(x.id)?tokenArt(x.icon):'<span aria-hidden="true">?</span>'}<p>${found.includes(x.id)?e(x.name):'Not discovered yet'}</p>${i<available?`<button class="text-button" data-revisit="${i}">Explore chapter ${i+1}</button>`:'<small>Reach this chapter to explore.</small>'}</div>`).join('')}</div><p class="small-note">${found.length} / ${EGGS.length} found. Optional discoveries never affect your grammar score.</p>${frogCollection()}`);
 const frogRoot=document.querySelector('#modalBody');bindFrogs(frogRoot);frogRoot.querySelectorAll('[data-frog-search]').forEach(b=>b.onclick=()=>{const f=FROGS.find(x=>x.id===b.dataset.frogSearch);if(!f||!frogReached(f,state))return;const setting=questionScene({stage:f.stage,id:f.stage===0?'m'+(f.view+1):'m'+(f.stage*5+1)},`${f.stage}-${f.view}`);showModal(`<span class="eyebrow">Look around · Chapter ${f.stage+1}</span><h2>${e(setting.name)}</h2><div class="journal-scene">${scene(false,false,f.stage,setting)}</div><p>There may be a quiet visitor here. Take your time.</p>`);const root=document.querySelector('#modalBody');paintFrame(root.querySelector('.painted-scene'),explorationFrameArt(f.stage,f.view));bindEasterEggs(root);});
 document.querySelector('#modalBody').querySelectorAll('[data-revisit]').forEach(b=>b.onclick=()=>{const stage=Number(b.dataset.revisit);showModal(`<span class="eyebrow">Look around · Chapter ${stage+1}</span><h2>${e(CASES[stage].title)}</h2><div class="journal-scene">${scene(false,false,stage)}</div><p>Something small is hiding in the illustration. Finding it will not change your grammar progress.</p>`);const root=document.querySelector('#modalBody');paintFrame(root.querySelector('.painted-scene'),explorationFrameArt(stage));bindEasterEggs(root);});
}
function earned(i){return state.decorations.some(d=>d.chapter===i);}
function skills(){return CHAPTERS.map(c=>`<div class="skill-row"><span>${e(c.blurb.replace(/\.$/,''))}</span><span class="tag ${mastered(state,c.skill)?'':'practice'}">${mastered(state,c.skill)?'Independent ✓':skillState(state,c.skill).attempts?'Practising':'To explore'}</span></div>`).join('');}
function warning(){return storageOK?'':'<div class="notice">Browser storage is unavailable. You can keep playing, but progress may disappear when you close this page.</div>';}
function reviewBanner(){const due=dueSkills(state);return due.length?`<div class="review-banner"><div><strong>Your trail is ready for a revisit.</strong><p>${due.length} skill${due.length===1?'':'s'} ready for a short memory check. Your adventure will wait.</p></div>${button('review','Take the memory trail')}</div>`:'';}
function home(){clearChapterView();music.setTense(false);screen='home';app.innerHTML=warning()+reviewBanner()+`<div class="hero"><div><span class="eyebrow">An autumn mystery · Go at your own pace</span><h1>${e(CASE_TITLE)}</h1><p class="muted">After the lantern fair, a light appears in the old mill. Join Poppy and Willow in a woodland mystery that begins with a light in an empty mill.</p><div class="button-row">${button('play',state.pendingReward!==undefined&&state.pendingReward!==null?'Collect your supplies':state.reviewRun?'Continue the memory trail →':state.bonus?'Continue the optional route →':state.story>=30?'Revisit the mystery ending':state.seq?'Continue the adventure →':'Meet Poppy & begin →')}${button('how','How to play','secondary')}${button('readStory','Open storybook','secondary')}${button('restartGame','Restart game','text-button restart-link')}</div><p class="small-note">Finish the mystery to uncover one last woodland secret. Six chapters. No timer or lost lives.</p></div>${scene()}</div><div class="section-top"><span class="eyebrow">The investigation</span><span class="muted small-note">${Math.floor(state.story/5)} of 6 expeditions complete</span></div><div class="path-map">${CHAPTERS.map((c,i)=>`<div class="map-stop ${earned(i)?'':i===chapter(state)?'active':'locked'}"><span class="num">${earned(i)?'✓ RESTORED':`0${i+1}`}</span>${buildingArt(i,!(!earned(i)&&i>chapter(state)))}<strong>${e(CASES[i].title)}</strong><small>${e(c.blurb)}</small></div>`).join('')}</div>`;
 document.querySelector('#readStory').onclick=storyBook;
 document.querySelector('#play').onclick=()=>{if(state.pendingReward!=null)reward(state.pendingReward);else if(state.activeId||state.reviewRun||state.bonus)begin();else if(state.story>=30)ending();else begin();};document.querySelector('#how').onclick=how;document.querySelector('#restartGame').onclick=requestRestart;bindEasterEggs();const r=document.querySelector('#review');if(r)r.onclick=()=>{if(state.activeId||state.reviewRun||state.bonus){showModal('<h2>Finish this crossing first.</h2><p>Your memory trail will wait for you.</p>');return;}startReview(state);save();begin();};presentMenuView('home');}
function begin(){if(state.pendingReward!=null)return reward(state.pendingReward);if(state.activeId||state.reviewRun||state.bonus)return play();const c=chapter(state);if(!state.introduced?.includes(c))return lesson(c);play();}
function lesson(c){clearChapterView();music.setMood(chapterMusicMood({stage:c}));screen='lesson';const x=CHAPTERS[c];app.innerHTML=warning()+`<div class="intro-card"><span class="eyebrow">Chapter ${c+1} / 6 · ${e(CASES[c].title)}</span><div class="case-opening">${tokenArt(CASES[c].icon)}<p>${e(CASES[c].intro)}</p></div><h2>${e(x.blurb)}</h2><p>${e(x.lesson)}</p>${x.demo?`<div class="example">${e(x.demo.join(', '))}</div>`:''}<p id="demoExplanation" class="muted">${c===0?'Try the full stop or comma + “but” below. Both can repair this crossing.':'Notice what makes this join work—or fail.'}</p><div id="demoTools" class="button-row">${c===0?button('demoStop','Try a full stop','secondary')+button('demoBut','Try comma + “but”','secondary'):x.demo?button('showDemo','Show me','secondary'):''}</div><div class="button-row">${button('startTrail','Start this expedition →')}</div><p class="small-note">Five sentence-editing notes${c===0?' and three short vocabulary, grammar and detective stops':c===1?' and four short notebook checks':c>=3?' and one two-part inference check':''}. A different example returns only after a structure needed help. Hints are always available.</p></div>`;
 function demo(tool){document.querySelector('.example').innerHTML=e(x.demo?renderSentence({parts:x.demo},[tool||x.fix]):'Read first. Then inspect any comma that looks doubtful.');document.querySelector('#demoExplanation').textContent=x.explain;}
 const a=document.querySelector('#demoStop'),b=document.querySelector('#demoBut'),d=document.querySelector('#showDemo');if(a)a.onclick=()=>demo('stop');if(b)b.onclick=()=>demo('but');if(d)d.onclick=()=>demo();document.querySelector('#startTrail').onclick=()=>{state.introduced=[...new Set([...(state.introduced||[]),c])];save();play();};presentMenuView('lesson');}
function storyBook(){const scenes=availableStoryScenes(state);showModal(`<span class="eyebrow">The story so far</span><h2>The Midnight Mill</h2><p>Return to any scene you have reached. Reading does not change your supplies, edits or hint status.</p><div class="storybook-index">${scenes.map((s,i)=>`<button class="secondary" data-book-scene="${s.id}">${i+1} · ${e(s.title)}</button>`).join('')}</div>`);document.querySelector('#modalBody').querySelectorAll('[data-book-scene]').forEach(b=>b.onclick=()=>readBookPage(b.dataset.bookScene,0));}
function readBookPage(id,page){const story=STORY_SCENES.find(s=>s.id===id);if(!story)return;const pages=window.matchMedia?.('(min-width:600px)').matches?textPages(story.paragraphs,48):readingPages(story);page=Math.max(0,Math.min(pages.length-1,page));const setting=questionScene({id,stage:story.stage||0});showModal(`<span class="eyebrow">Storybook · Chapter ${(story.stage||0)+1} · Scene ${(Number(id.slice(1))-1)%5+1} of 5</span><h2>${e(story.title)}</h2><div class="artwork-preview" role="img" aria-label="${e(story.location)}" style="background-image:url('assets/${setting.asset}');background-size:${setting.scale};background-position:${setting.focus}"></div><div class="story-prose">${pages[page].map(p=>`<p>${storyProseHTML(p,e)}</p>`).join('')}</div><div class="story-controls">${button('bookPrevious','← Previous','secondary')}${button('bookNext',page===pages.length-1?'Back to scenes':'Continue →')}</div><p class="small-note">Page ${page+1} of ${pages.length}</p>`);const body=document.querySelector('#modalBody');paintFrame(body.querySelector('.artwork-preview'),textFrameArt(id,pages[page].join(' ')));body.querySelector('#bookPrevious').onclick=()=>page?readBookPage(id,page-1):storyBook();body.querySelector('#bookNext').onclick=()=>page===pages.length-1?storyBook():readBookPage(id,page+1);}
function showStory(q){
 screen='story';const story=readingScene(state,q),storyQ={id:story.id,stage:q.stage},pages=readingPages(story),page=storyPosition(state,story.id),last=page===pages.length-1;
 setStoryPosition(state,story.id,page);if(!window.matchMedia?.('(min-width:600px)').matches)observeNotebookText(state,story.id,pages[page].join(' '));save();
 app.innerHTML=warning()+`<div class="story-heading"><span class="eyebrow">Chapter ${q.stage+1} · ${e(CASES[q.stage].title)}</span><h2>${e(story.title)}</h2><p>${e(story.location)} · Scene ${(Number(story.id.slice(1))-1)%5+1} / 5</p></div><section class="story-reader"><div class="story-illustration">${scene(false,false,q.stage,questionScene(storyQ))}<button id="storyArtwork" class="text-button">View artwork ↗</button></div><div class="story-page"><div class="story-prose">${pages[page].map(p=>`<p class="${p.startsWith('“')?'spoken-line':'narration'}">${storyProseHTML(p,e)}</p>`).join('')}</div><div class="story-controls"><button id="storyPrevious" class="secondary" ${page===0?'disabled':''}>← Back</button>${button('storyNext',last?(q.stage>=1&&Number(story.id.slice(1))%5!==0?'Continue the story →':'Open the language notes →'):'Continue →')}</div><p class="story-page-count">Page ${page+1} / ${pages.length}</p></div></section>`;
 document.querySelector('#storyPrevious').onclick=()=>{setStoryPosition(state,story.id,page-1);save();showStory(q);};
 document.querySelector('#storyNext').onclick=()=>{if(last){finishStoryScene(state,story.id);save();if(needsStory(state,q))showStory(q);else openNotebook(q);}else{setStoryPosition(state,story.id,page+1);save();showStory(q);}};
 document.querySelector('#storyArtwork').onclick=()=>{const frame=FRAME_ART.find(f=>f.id===app.querySelector('.story-illustration .painted-scene')?.dataset.frameArt)||textFrameArt(story.id,pages[page].join(' '));const setting=questionScene(storyQ);showModal(`<h2>${e(story.title)}</h2><div class="artwork-preview" role="img" aria-label="${e(story.location)}" style="background-image:url('assets/${setting.asset}');background-size:${setting.scale};background-position:${setting.focus}"></div>`);paintFrame(document.querySelector('#modalBody .artwork-preview'),frame);};
 paintFrame(app.querySelector('.story-illustration .painted-scene'),textFrameArt(story.id,pages[page].join(' ')));presentChapterView({kind:'story',title:story.title,chapter:q.stage+1,onReadingPart:(part,text)=>{observeNotebookText(state,story.id,text.join(' '));save();paintFrame(app.querySelector('.story-illustration .painted-scene'),textFrameArt(story.id,text.join(' ')));}});bindEasterEggs();app.querySelector('.story-heading')?.scrollIntoView?.({block:'start',behavior:'auto'});say(story.title+'. Page '+(page+1)+' of '+pages.length+'.');
}
function play(){screen='play';feedback=null;solved=false;selected=-1;const q=nextQuestion(state);if(!q)return home();music.setMood(!state.reviewRun&&!state.bonus?chapterMusicMood(q):'calm');selectQuestionScene(state,q);save();if(needsStory(state,q))return showStory(q);if(state.pendingNotebook===q.id){const after=caseworkFor(state,q,'after');if(after)return showCasework(q,after);if(!errors(q,state.activeChoices).length&&wordOrderCorrect(q,state.activeWordOrder))return advance();state.pendingNotebook=null;}openNotebook(q);}

function openNotebook(q){const task=caseworkFor(state,q);if(task){showCasework(q,task);app.querySelector('.story-heading')?.scrollIntoView?.({block:'start',behavior:'auto'});return;}screen='play';draw();app.querySelector('.game-heading')?.scrollIntoView?.({block:'start',behavior:'auto'});}
function showCasework(q,task,message=''){activeCasework=task;
 screen='casework';const work=caseworkState(state,task.id),route=task.routes?.find(r=>r.id===work.route),choosing=task.routes&&!route;
 const optionButtons=(items,key)=>items.map(o=>`<button class="casework-option ${work[key]===o.id?'chosen':''}" data-case-${key}="${o.id}" aria-pressed="${work[key]===o.id}" ${work.completed?'disabled':''}>${e(o.text)}</button>`).join('');
 const words=task.kind==='grammar'?task.text.split(' '):[];
 const edit=task.kind==='grammar'?`<div class="casework-edit" aria-label="Choose the incorrect word">${words.map((w,i)=>`<button class="editable-word ${work.choice===String(i)?'chosen':''}" data-case-choice="${i}" aria-pressed="${work.choice===String(i)}" ${work.completed?'disabled':''}>${e(work.completed&&i===task.word?task.answer:w)}</button>`).join(' ')}</div><label class="correction-label" for="caseCorrection">Replace ${work.choice!==''?'“'+e(words[Number(work.choice)])+'”':'the selected word'} with:</label><input id="caseCorrection" class="case-correction" type="text" value="${e(work.correction)}" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="30" ${work.completed?'disabled':''}>`: `<div class="casework-options" role="group" aria-label="Choose a conclusion">${optionButtons(task.options,'choice')}</div>${task.evidence?`<h3>Part 2: Which pair of details provides the strongest support?</h3><div class="casework-options" role="group" aria-label="Choose supporting evidence">${optionButtons(task.evidence,'evidence')}</div>`:''}`;
 app.innerHTML=warning()+`<div class="story-heading"><span class="eyebrow">Chapter ${q.stage+1} · ${e(task.label)}</span><h2>${e(task.title)}</h2><p>Poppy opens her notebook.</p></div><section class="casework-reader"><div class="casework-art">${scene(false,false,q.stage,questionScene(q))}</div><div class="casework-page">${choosing?`<p>“Where should we look first?” Willow asks.</p><p>Choose where to look first. You’ll have the same clues whichever path you take.</p><div class="casework-options">${task.routes.map(r=>`<button class="casework-option" data-case-route="${r.id}">${e(r.text)}</button>`).join('')}</div>`:`${route?`<p class="lead-observation">${e(route.observation)}</p>`:''}<blockquote class="casework-context">${e(task.context)}</blockquote><p class="casework-prompt">${e(task.kind==='deduction'?task.prompt.split('\n')[0]:task.prompt)}</p>${edit}${message?`<div class="casework-feedback ${work.completed?'complete':''}" role="status">${e(message)}</div>`:''}${work.completed?`<p>${e(task.success)}</p><details class="edit-explanation"><summary>Read the reasoning</summary><p>${e(task.why)}</p></details>${button('caseworkContinue','Continue →')}`:`<div class="casework-actions">${button('caseworkHint','Ask for a clue','text-button')}${button('caseworkCheck',task.kind==='grammar'?'Check the edit →':'Check the reasoning →')}</div>`}`}</div></section>`;
 app.querySelectorAll('[data-case-route]').forEach(b=>b.onclick=()=>{updateCasework(state,task.id,{route:b.dataset.caseRoute});save();showCasework(q,task);});
 for(const key of ['choice','evidence'])app.querySelectorAll(`[data-case-${key}]`).forEach(b=>b.onclick=()=>{if(work.completed)return;updateCasework(state,task.id,{[key]:b.dataset[key==='choice'?'caseChoice':'caseEvidence']});save();showCasework(q,task);app.querySelector(`[data-case-${key}="${b.dataset[key==='choice'?'caseChoice':'caseEvidence']}"]`)?.focus();});
 const input=document.querySelector('#caseCorrection');if(input)input.oninput=()=>{if(work.completed)return;updateCasework(state,task.id,{correction:input.value});save();};
 const hint=document.querySelector('#caseworkHint');if(hint)hint.onclick=()=>{updateCasework(state,task.id,{hinted:true});save();showCasework(q,task,task.hint);document.querySelector('#caseworkHint')?.focus();say(task.hint);};
 const check=document.querySelector('#caseworkCheck');if(check)check.onclick=()=>{
  const latest=caseworkState(state,task.id);let text;
  if(!latest.choice||(task.kind==='deduction'&&!latest.evidence)||(task.kind==='grammar'&&!latest.correction.trim()))text=task.kind==='grammar'?'Choose the incorrect word and enter its replacement.':(task.kind==='deduction'?'Pick a conclusion and the details that support it.':'Choose an answer before checking.');
  else if(submitCasework(state,task))text=task.kind==='grammar'?'The note is clear.':task.kind==='deduction'?'Your conclusion stays within the evidence.':task.kind==='reasoning'?'The reasoning is clear.':'That reading fits the context.';
  else text=task.kind==='grammar'?(latest.choice!==String(task.word)?'Check whether the word you selected is actually ungrammatical. Find the subject and its verb.':'Keep the note in the past tense and make the verb agree with its subject.'):task.kind==='deduction'&&latest.choice===task.answer?(task.evidenceHint||'Your conclusion is sound. Now find the two details that identify this particular coat.'):task.options.find(o=>o.id===latest.choice)?.feedback||'Look at what the passage establishes, rather than what might have happened.';
  save();showCasework(q,task,text);document.querySelector(caseworkState(state,task.id).completed?'#caseworkContinue':'#caseworkCheck')?.focus();say(text);
 };
 const next=document.querySelector('#caseworkContinue');if(next)next.onclick=()=>{if(caseworkState(state,task.id).completed){if(task.phase==='after')advance();else openNotebook(q);}};
 presentChapterView({kind:'casework',chapter:q.stage+1,title:task.title,key:task.id,message,completed:work.completed});paintFrame(app.querySelector('.casework-art .painted-scene'),caseworkFrameArt(task.id));
 bindEasterEggs();
}

function sentenceMarkup(q){return sentenceParts(q,state.activeWordOrder).map((part,i)=>{
 let p=part;if(i&&state.activeChoices[i-1]==='stop')p=p.charAt(0).toUpperCase()+p.slice(1);
 if(i===q.parts.length-1)return e(p);
 const tail=p.match(/(\S+)$/),word=tail?.[0]||'',head=p.slice(0,p.length-word.length),t=state.activeChoices[i];
 return e(head)+`<span class="join-anchor">${e(word)}<button class="join ${selected===i?'selected':''} ${feedback?.bad?.includes(i)?'bad':''}" data-join="${i}" aria-label="Inspect join ${i+1}: ${e(TOOLS[t].label)}" aria-pressed="${selected===i}" ${solved?'disabled':''}>${e(TOOLS[t].join.trim())}</button></span> `;
 }).join('');}

const CHAPTER_PAYOFFS={m6:'Two circular marks lie sheltered from the rain.',m7:'The rain has affected the exposed and sheltered marks differently.',m8:'Willow searches the bank by lamplight.',m9:'Their next step is still a choice.',m10:'The circular mark and deep bootprints belong in the same account.',m1:'Beyond the gardens, the mill’s upper window glows.',m2:'A scraping sound carries through the rain.',m3:'The light vanishes. The mill draws back into the trees.',m4:'Poppy knows those crooked yellow stitches. They are hers.',m5:'Something knocks beyond the porch. No footsteps follow.'};
function compactBrief(q){return q.studentBrief;}
function storyPayoff(q){return `<div class="story-payoff ${q.id==='m5'?'bell-payoff':''}" role="status"><span class="eyebrow">In Poppy’s notebook</span><p>${e((CHAPTER_PAYOFFS[q.id]||'Poppy saves the observation.'))}</p></div>`;}
function bellTone(){if(!sound)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)();[392,784,1054].forEach((hz,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.frequency.value=hz;g.gain.setValueAtTime(.025/(i+1),ac.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+1.8);o.start();o.stop(ac.currentTime+1.9);});setTimeout(()=>ac.close(),2100);}catch{}}

function currentTools(q){return q.options;}
function socket(q,i=0){const t=state.activeChoices[i];return `<button class="join crossing-socket ${selected===i?'selected':''} ${feedback?.bad?.includes(i)?'bad':''}" data-join="${i}" aria-label="Fit a piece at join ${i+1}: ${e(TOOLS[t].label)}" aria-pressed="${selected===i}" ${solved?'disabled':''}><span class="socket-mark">${e(TOOLS[t].join.trim())}</span><span class="socket-caption">${t==='comma'?'inspect join':'piece fitted'}</span></button>`;}
function crossingWords(q){return `<div class="reading-chart ${q.kind==='paragraph'?'passage-chart':''}"><span class="chart-pin"></span>${q.stage<=5?`<div class="notebook-source"><span>${q.remedial?'An earlier note · Recall practice':'Your turn · '+e(storyScene(q)?.title||'After the fair')}</span><button id="readStory" class="text-button">Story so far</button></div>`:''}<p class="editing-brief"><b>Your task:</b> ${e(compactBrief(q))}</p><button id="editingRules" class="text-button editing-rules-toggle">Editing rules</button><div class="sentence" aria-label="Route to scout">${sentenceMarkup(q)}</div>${q.wordOrder?`<label class="correction-label" for="clauseRewrite">Rewrite the second clause without the conjunction:</label><input id="clauseRewrite" class="case-correction" type="text" value="${e(state.activeWordOrder||'')}" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="120" ${solved?'disabled':''}>`:''}</div>`;}
function toolArt(t){const split=t==='stop';return `<svg viewBox="0 0 110 37" aria-hidden="true"><path d="M7 30H103" stroke="#9c744a" stroke-width="3" stroke-linecap="round"/><path d="M12 9H${split?'45':'98'}V29H12Z" fill="#e6c48b" stroke="#a67b48" stroke-width="2"/>${split?'<path d="M65 9H98V29H65Z" fill="#e6c48b" stroke="#a67b48" stroke-width="2"/>':''}<path d="M19 12V26M90 12V26" stroke="#f8e1b3" stroke-width="2"/></svg>`;}
function draw(){
 const q=BANK.find(x=>x.id===state.activeId),assisted=state.activeHelp||state.activeTries>0;
 const mode=state.reviewRun?'Memory trail':state.bonus?'Secret trail':q.remedial?'Recovery crossing':CASES[q.stage].title;
 const total=state.reviewRun?.skills.length??state.bonus?.skills.length??5;
 const progress=state.reviewRun?.index??state.bonus?.index??state.step;
 const placed=state.activeChoices.some(t=>t!=='comma');
 app.innerHTML=warning()+`<div class="game-heading"><div><span class="eyebrow">${e(mode)} · ${state.reviewRun||state.bonus?'A little extra exploring':`Expedition ${chapter(state)+1} of 6`}</span><h2>${solved?'Note saved.':q.kind==='paragraph'?'Edit the case report.':'Poppy’s notebook'}</h2></div><div class="supply-trail compact-supply" aria-label="${progress} of ${total} crossings completed"><span>${e(currentBuild(state)?.short||'Your village')} · ${progress}/${total} ${state.reviewRun||state.bonus?'notes':'supplies'}</span><button id="buildPeek" class="build-peek" aria-label="See your village build">See build ↗</button></div></div>
 <div class="adventure-board many-joins scouting-board art-first ${solved?'celebrating':''} ${feedback&&!solved?'needs-adjustment':''}">
  <div class="world-stage">${scene(solved,placed,q.stage,questionScene(q,state.activeScenery?.key),questionFrameArt(q.id))}${solved&&!assisted&&!state.reviewRun&&!state.bonus?'<div class="spark-flight" aria-hidden="true">✦</div>':''}<button id="viewArtwork" class="text-button artwork-link" aria-label="View artwork" title="View artwork"><span aria-hidden="true">↗</span></button>${solved&&storyScene(q)&&!state.reviewRun&&!state.bonus?storyPayoff(q):''}</div><div class="case-workspace">${crossingWords(q)}

  <div class="builder-dock"><div class="dock-heading"><span class="eyebrow">${selected<0?'Scout first. Change only what needs changing.':'Join '+(selected+1)+' · Fit a piece'}</span><span class="dock-note">${selected<0?'The full route is your decision.':'Drag or tap · keep the story’s meaning'}</span></div><div class="piece-tray" role="group" aria-label="Sentence pieces">${selected<0?`<span class="scout-prompt">${q.joinTask?'Tap the full stop to join the two sentences.':'Tap a comma to edit, or check the note as it is.'}</span>`:currentTools(q).map(t=>`<button class="sentence-piece ${state.activeChoices[selected]===t?'chosen':''}" data-tool="${t}" draggable="${!solved}" aria-label="${e(TOOLS[t].label)}: fit at join ${selected+1}" aria-pressed="${state.activeChoices[selected]===t}" ${solved?'disabled':''}>${toolArt(t)}<b>${e(TOOLS[t].mark)}</b><span>${e(TOOLS[t].label)}</span></button>`).join('')}</div>
  ${feedback?`<div class="feedback ${solved?'':'clue'}" role="status">${solved?'':`<span class="feedback-poppy" aria-hidden="true">${rabbitArt(false)}</span>`}<div><strong>${e(feedback.title)}</strong>${feedback.html||e(feedback.text)}</div></div>`:''}
  ${!solved&&!state.reviewRun&&!state.bonus&&contractAvailable(q)?`<button id="contract" class="route-contract ${state.activeContract?'accepted':''}" aria-pressed="${!!state.activeContract}"><span>✦✦</span> ${state.activeContract?'Challenge accepted: keep it as ONE sentence':'Take the lantern challenge: keep it as ONE sentence'}<small>${state.activeContract?'Tap to return to the regular route.':'Two sparks for an independent solve. No speed limit.'}</small></button>`:''}<div class="actions">${solved&&q.id==='m15'?button('endingReflection','Optional: Poppy’s decision','text-button'):''}${!solved?button('hint','◌ Ask Poppy for a hint','hint-button'):`<span class="small-note">${assisted?'Note saved · we’ll revisit this kind of join':(state.reviewRun||state.bonus?'✦ Recall spark to collect':state.activeContract?'✦✦ Two beacon sparks to collect':'✦ One beacon spark to collect')}</span>`}${button(solved?'next':'check',solved?'Collect supplies & continue →':'Check the note →')}</div></div></div>
 </div>`;
 const rewrite=document.querySelector('#clauseRewrite');if(rewrite)rewrite.oninput=()=>{state.activeWordOrder=rewrite.value;feedback=null;save();document.querySelector('.sentence').innerHTML=sentenceMarkup(q);bindJoins();};
 const book=document.querySelector('#readStory');if(book)book.onclick=storyBook;
 document.querySelector('#editingRules').onclick=()=>showModal(`<h2>Editing rules</h2><p>${e(q.wordOrder?'Join the sentences, then rewrite the second clause to fit the second negative. Change its word order and remove the repeated negative where necessary.':q.joinTask?'Join the two sentences into one. Keep every word, changing an initial capital to lower case where necessary. Put a comma before a coordinating conjunction.':EDITING_RULES)}</p><p>${q.joinTask?'Tap the full stop to choose a new join. The punctuation pieces include their commas.':'Read the whole note quietly in your head. Tap a comma to inspect or change it. Some commas already belong there.'}</p><p>Another repair may be grammatical but miss the writing goal. That does not count as a grammar mistake.</p>`);
 function bindJoins(){
 app.querySelectorAll('[data-join]').forEach(b=>{
  b.onclick=()=>{selected=Number(b.dataset.join);draw();app.querySelector(`[data-join="${selected}"]`)?.focus();};
  b.ondragover=ev=>{if(solved)return;ev.preventDefault();b.classList.add('drop-ready');};
  b.ondragleave=()=>b.classList.remove('drop-ready');
  b.ondrop=ev=>{ev.preventDefault();b.classList.remove('drop-ready');if(solved)return;const t=ev.dataTransfer.getData('text/plain');if(!currentTools(q).includes(t))return;selected=Number(b.dataset.join);fitPiece(t);};
 });
 }
 bindJoins();
 app.querySelectorAll('[data-tool]').forEach(b=>{
  b.onclick=()=>fitPiece(b.dataset.tool);
  b.ondragstart=ev=>{ev.dataTransfer.setData('text/plain',b.dataset.tool);ev.dataTransfer.effectAllowed='copy';b.classList.add('lifting');};
  b.ondragend=()=>{b.classList.remove('lifting');app.querySelectorAll('.drop-ready').forEach(x=>x.classList.remove('drop-ready'));};
 });
 document.querySelector('#buildPeek').onclick=peekVillage;
 const reflection=document.querySelector('#endingReflection');if(reflection)reflection.onclick=endingReflection;
 const h=document.querySelector('#hint');if(h)h.onclick=hint;
 const test=document.querySelector('#check');if(test)test.onclick=check;
 const next=document.querySelector('#next');if(next)next.onclick=advance;
 bindEasterEggs();document.querySelector('#viewArtwork').onclick=()=>{const setting=questionScene(q,state.activeScenery?.key);showModal(`<span class="eyebrow">Chapter ${q.stage+1} · Look around</span><h2>${e(setting.name)}</h2><div class="artwork-preview" role="img" aria-label="${e(setting.name)}" style="background-image:url('assets/${setting.asset}');background-size:${setting.scale};background-position:${setting.focus}"></div><p class="small-note">Take your time. Your question and edits are waiting.</p>`);paintFrame(document.querySelector('#modalBody .artwork-preview'),questionFrameArt(q.id));};const contract=document.querySelector('#contract');if(contract)contract.onclick=()=>{state.activeContract=!state.activeContract;feedback=null;save();draw();document.querySelector('#contract')?.focus();};
 paintFrame(app.querySelector('.world-stage .painted-scene'),questionFrameArt(q.id));
 if(q.stage<=5)presentChapterView({kind:'question',chapter:q.stage+1,title:'Poppy’s language notes',onDismiss:()=>{feedback=null;draw();}});else clearChapterView();
}
function fitPiece(t){if(solved||selected<0)return;state.activeChoices[selected]=t;feedback=null;save();draw();say(`${TOOLS[t].label} fitted. ${renderSentence(BANK.find(q=>q.id===state.activeId),state.activeChoices,state.activeWordOrder)}`);app.querySelector(`[data-tool="${t}"]`)?.focus();}
function endingReflection(){
 const t=CHAPTER_THREE_REFLECTION;
 showModal(`<span class="eyebrow">Optional inference · No supplies needed</span><h2>${e(t.title)}</h2><p>${e(t.context)}</p><p>${e(t.prompt)}</p><div class="casework-options">${t.options.map(o=>`<button class="casework-option" data-reflection="${o.id}">${e(o.text)}</button>`).join('')}</div><p id="reflectionFeedback" role="status"></p>`);
 document.querySelector('#modalBody').querySelectorAll('[data-reflection]').forEach(b=>b.onclick=()=>{const o=t.options.find(o=>o.id===b.dataset.reflection);document.querySelector('#modalBody').querySelector('#reflectionFeedback').textContent=o.id===t.answer?t.why:o.feedback;});
}
function hint(){if(selected<0)selected=0;const q=BANK.find(x=>x.id===state.activeId);state.activeHelp=true;save();feedback={title:'Read it quietly in your head.',html:`<div class="standalone"><div>${e(q.parts[selected])}</div><div>${e(q.parts[selected+1])}</div></div><p>Try each side as a sentence. Does it have its own subject and verb? An opening word such as <b>“although”</b> can leave you waiting for the rest.</p><p><b>What the note needs:</b> ${e(q.brief)}</p><p>${e(q.why[selected])}</p><span class="small-note">Listen to the rhythm, then check the clauses. A pause alone doesn’t tell you which punctuation to use.</span>`};draw();document.querySelector('#hint')?.focus();say('Poppy’s hint is open.');}
function check(){const q=BANK.find(x=>x.id===state.activeId);
 if(q.wordOrder&&!wordOrderCorrect(q,state.activeWordOrder)){
  state.activeTries++;state.activeHelp=true;save();feedback={title:'Check the second negative.',text:'Rewrite the second clause as well as choosing the join. After the negative conjunction, check the position of the auxiliary verb and whether another negative is needed.'};draw();document.querySelector('#clauseRewrite')?.focus();say(feedback.text);return;
 }
 const bad=errors(q,state.activeChoices);if(bad.length&&!grammarErrors(q,state.activeChoices).length){feedback={title:'This works, but check what Poppy needs.',text:'Your sentence is grammatical. Now try the edit described here: '+q.studentBrief};draw();document.querySelector('#check')?.focus();say(feedback.text);}else if(bad.length){state.activeTries++;state.activeHelp=true;selected=grammarErrors(q,state.activeChoices)[0];save();feedback={title:state.activeTries===1?'One join needs another look.':'Let’s look at this join together.',bad:[selected],text:'Read the highlighted join again. Can each side stand as a sentence? If you’re stuck, ask Poppy for a hint.'};draw();document.querySelector('#check')?.focus();say(feedback.text);}else if(state.activeContract&&!contractMet(q,state.activeChoices)){feedback={title:'Grammatically correct. Now try the lantern challenge.',text:'Keep these ideas in one sentence. A semicolon or a suitable joining word may help. Or turn off the challenge and use your valid repair. No mistake has been counted.'};draw();document.querySelector('#check')?.focus();say(feedback.text);}else{solved=true;feedback={title:'The note is clear.',html:(storyScene(q)&&!state.reviewRun&&!state.bonus?`<p class="note-consequence">${e((CHAPTER_PAYOFFS[q.id]||'Poppy saves the observation.'))}</p>`:'')+`<details class="edit-explanation"><summary>Why this edit works</summary>${q.why.map(w=>`<p>${e(w)}</p>`).join('')}</details>`};draw();if(q.id!=='m5'||state.reviewRun||state.bonus)chime();say('The note is clear. '+(storyScene(q)&&!state.reviewRun&&!state.bonus?(CHAPTER_PAYOFFS[q.id]||'Poppy saves the observation.'):'Continue when you are ready.'));document.querySelector('#next').focus();}}
function advance(){const q=BANK.find(x=>x.id===state.activeId);const after=caseworkFor(state,q,'after');if(after){state.pendingNotebook=q.id;save();return showCasework(q,after);}state.pendingNotebook=null;const wasReview=!!state.reviewRun,wasBonus=!!state.bonus;const result=record(state,q,state.activeHelp||state.activeTries>0);lastResult=result;if(result.chapterDone){state.pendingReward=result.chapter;save();return reward(result.chapter);}save();if(wasReview&&!state.reviewRun)return reviewDone();if(result.bonusFinished)return bonusDone(result.earned);play();}
function reward(c){clearChapterView();music.setTense(false);screen='reward';const decors=finishingTouches(c);let choice=0;app.innerHTML=warning()+`<div class="finish-card"><span class="eyebrow">Expedition ${c+1} complete · Supplies delivered</span><h2>${e(CHAPTERS[c].reward)}</h2><div class="chapter-clue">${tokenArt(CASES[c].icon)}<p>${e(CASES[c].clue)}</p></div><div class="finishing-picker"><div id="rewardVillage" class="village-reward-art reward-reveal">${villageMarkup(state,{interactive:false,previewChapter:c,previewDecor:decors[0]})}</div><div class="finishing-palette"><p>Your five deliveries built this landmark. Choose its finishing touch and see it become part of the village.</p><div class="decorations" aria-label="Finishing-touch choices">${decors.map((d,i)=>`<button class="decoration ${i===0?'chosen':''}" data-decor="${i}" aria-pressed="${i===0}"><img src="${d.image}" alt="" draggable="false"><span>${e(d.name)}</span></button>`).join('')}</div><p class="finishing-description" id="finishingDescription" aria-live="polite">${e(decors[0].description)}</p></div></div>${button('collect',c===5?'Finish the village & reveal the ending →':'Finish it & return to the trail →')}<p class="small-note">Your reward belongs to you. Hints never take it away.</p></div>`;app.querySelectorAll('[data-decor]').forEach(b=>b.onclick=()=>{choice=Number(b.dataset.decor);app.querySelectorAll('[data-decor]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b));});document.querySelector('#rewardVillage').innerHTML=villageMarkup(state,{interactive:false,previewChapter:c,previewDecor:decors[choice]});document.querySelector('#finishingDescription').innerHTML=e(decors[choice].description);});document.querySelector('#collect').onclick=()=>{if(!earned(c))state.decorations.push({chapter:c,id:decors[choice].id,name:decors[choice].name});state.pendingReward=null;save();if(c===5)ending();else home();};presentMenuView('reward');}

function reviewDone(){clearChapterView();screen='reviewDone';app.innerHTML=`<div class="finish-card"><span class="eyebrow">Memory trail complete</span><h2>A little surer.</h2><p>You have revisited the skills that were ready. Only structures that needed support return. Successful recall spaces their next checks to three and then seven days; supported practice gets another check tomorrow.</p><p class="muted">There is no daily streak to lose. Come back when you can.</p>${skills()}<div class="button-row">${button('return','Return to your adventure →')}</div></div>`;document.querySelector('#return').onclick=home;presentMenuView('reviewDone');}
function bonusDone(earnedBonus){clearChapterView();if(earnedBonus&&!state.bonusDecor){state.bonusDecor=true;save();}screen='bonusDone';app.innerHTML=`<div class="finish-card"><span class="eyebrow">Optional route complete</span><h2>${earnedBonus?'A special find.':'A useful journey.'}</h2><p>${earnedBonus?'You solved three challenge crossings independently. A fountain has been added to the village.':'Some crossings needed support. Your successful challenge crossings stay complete. Next time, you only revisit the skills that needed help.'}</p><div class="village-reward-art">${villageMarkup(state,{interactive:false})}</div><div class="button-row">${button('return','Visit your village →')}</div></div>`;document.querySelector('#return').onclick=village;presentMenuView('bonusDone');}
function nextDates(){return CHAPTERS.filter(c=>skillState(state,c.skill).due).map(c=>{const x=skillState(state,c.skill);const days=Math.max(0,Math.ceil((x.due-Date.now())/DAY));return `<div class="skill-row"><span>${e(c.name)}</span><span>${days===0?'Ready now':`In ${days} day${days===1?'':'s'}`} · ${x.level?'Later recall ✓':'First revisit pending'}</span></div>`;}).join('');}
function changeFinishingTouch(c){
 if(c<0||c>5||!earned(c))return;
 const decors=finishingTouches(c),old=state.decorations.find(d=>d.chapter===c);
 let choice=Math.max(0,decors.findIndex(d=>d.id===old.id||d.name===old.name));
 showModal(`<h2>${e(CHAPTERS[c].reward)}</h2><p>Choose a new finishing touch for this place.</p><div id="touchPreview" class="touch-preview">${villageMarkup(state,{interactive:false,previewChapter:c,previewDecor:decors[choice]})}</div><div class="decorations" aria-label="Finishing-touch choices">${decors.map((d,i)=>`<button class="decoration ${i===choice?'chosen':''}" data-touch-select="${i}" aria-pressed="${i===choice}"><img src="${d.image}" alt="" draggable="false"><span>${e(d.name)}</span></button>`).join('')}</div><p id="touchDescription" class="finishing-description" aria-live="polite">${e(decors[choice].description)}</p>${button('saveTouch','Save finishing touch')}`);
 const body=document.querySelector('#modalBody');
 body.querySelectorAll('[data-touch-select]').forEach(b=>b.onclick=()=>{
  choice=Number(b.dataset.touchSelect);
  body.querySelectorAll('[data-touch-select]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b));});
  body.querySelector('#touchPreview').innerHTML=villageMarkup(state,{interactive:false,previewChapter:c,previewDecor:decors[choice]});
  body.querySelector('#touchDescription').innerHTML=e(decors[choice].description);
 });
 body.querySelector('#saveTouch').onclick=()=>{const i=state.decorations.findIndex(d=>d.chapter===c);state.decorations[i]={...state.decorations[i],id:decors[choice].id,name:decors[choice].name};save();modal.close();village();};
}

function buildNote(){const p=currentBuild(state);return p?`<div class="village-current"><span class="eyebrow">${p.ready?'The finishing touch':'Currently building'}</span><div><strong>${e(p.name)}</strong></div><p>${e(stageLabel(p))} · ${p.delivered} / ${p.total} deliveries</p><div class="construction-dots" aria-hidden="true">${Array.from({length:5},(_,i)=>`<span class="${i<p.delivered?'delivered':''}"></span>`).join('')}</div></div>`:'<p class="village-caption">All six landmarks are finished. Your village is home.</p>';}
function peekVillage(){showModal(`<h2>Your village is growing.</h2><div class="village-world">${villageMarkup(state,{interactive:false})}</div>${buildNote()}<p class="small-note">Each new story crossing delivers another part. Your question and edits are waiting.</p><div class="button-row">${button('openVillage','Explore your village','secondary')}</div>`);document.querySelector('#modalBody').querySelector('#openVillage').onclick=()=>{modal.close();village();};}
function village(){clearChapterView();music.setTense(false);screen='village';app.innerHTML=warning()+reviewBanner()+`<div class="section-top"><div><span class="eyebrow">Built one delivery at a time</span><h1>The lantern-lit village.</h1></div></div><div class="village-world"><div class="village-toolbar"><p>${e(villageSummary(state))}</p><button id="villageZoom" class="text-button" aria-pressed="false">Zoom in +</button></div>${villageMarkup(state)}<p class="village-caption">Tap a small marker to visit a landmark. Zoom in and scroll around to look closer.</p></div>${buildNote()}<div class="village-scene-actions">${button('caseNotes','Your case notes','secondary')}${button('readStory','Open storybook','secondary')}${button('villageLearning','Learning & memory trails','secondary')}${state.story>=30?button('endingReplay','Revisit the mystery ending','secondary'):''}</div><div class="button-row">${button('back',state.story>=30?'Back to the trail map':'Continue your adventure →')}${state.story>=30?button('bonus',state.bonusDecor?'Bonus fountain earned':'Build the bonus fountain','secondary'):''}</div>`;
 let zoomed=false;document.querySelector('#villageZoom').onclick=()=>{zoomed=!zoomed;app.querySelector('.village-viewport').setAttribute('data-zoom',zoomed?'2':'1');const b=document.querySelector('#villageZoom');b.textContent=zoomed?'Fit village −':'Zoom in +';b.setAttribute('aria-pressed',String(zoomed));};
 app.querySelectorAll('[data-village-site]').forEach(b=>b.onclick=()=>{const p=siteProgress(state,Number(b.dataset.villageSite));showModal(`<span class="eyebrow">${p.index===6?'Optional route reward':'Expedition '+(p.index+1)}</span><h2>${e(p.name)}</h2><p class="landmark-stage">${e(stageLabel(p))}</p><p class="landmark-deliveries">${p.delivered} / ${p.total} ${p.index===6?'independent challenges':'supply deliveries'}</p>${p.decoration?`<p>Finishing touch: ${e(p.decoration.name)}</p>`:''}${p.beacon?'<p>✦ Your beacon is lit.</p>':''}${p.finished&&p.index<6?button('changeTouch','Change finishing touch','secondary'):''}<p class="small-note">${p.index===6?(p.finished?'Your fountain is part of the village.':'Complete the three optional challenges independently to finish the fountain. Successful challenges stay complete.'):(p.ready?'Your supplies are delivered. Return to the adventure to choose your finishing touch.':p.finished?'This finished landmark stays yours.':'Each new story crossing brings the next part. Hints never take your supplies away.')}</p>`);const edit=document.querySelector('#modalBody').querySelector('#changeTouch');if(edit)edit.onclick=()=>changeFinishingTouch(p.index);});
 document.querySelector('#readStory').onclick=storyBook;
 document.querySelector('#caseNotes').onclick=()=>showModal(evidenceBoard());
 document.querySelector('#villageLearning').onclick=()=>{showModal('<h2>Skills that are growing</h2>'+skills()+'<h3>Your next memory trails</h3><p>Only structures that needed help return after about 1 day, then 3 and 7 days following successful recall. No daily streaks.</p>'+nextDates());};
 const replay=document.querySelector('#endingReplay');if(replay)replay.onclick=ending;document.querySelector('#back').onclick=()=>{if(state.activeId||state.reviewRun||state.bonus||state.story<30)begin();else home();};const b=document.querySelector('#bonus');if(b)b.onclick=()=>{if(state.activeId||state.reviewRun||state.bonus)return begin();if(!startBonus(state)){showModal('<h2>Fountain already earned.</h2><p>You have completed all three optional challenges independently. Your rewards stay yours.</p>');return;}save();play();};const r=document.querySelector('#review');if(r)r.onclick=()=>{if(state.activeId||state.bonus||state.reviewRun){showModal('<h2>Finish this crossing first.</h2><p>Your memory trail will wait for you.</p>');return;}startReview(state);save();play();};presentMenuView('village');}

function ending(){clearChapterView();
 if(state.story<30)return home();music.setTense(false);screen='ending';state.endingSeen=true;save();
 const found=discoveryList(state.easterEggs);
 app.innerHTML=warning()+`<section class="mystery-ending"><span class="eyebrow">Case closed · Before morning</span><h1>Everyone home.</h1><div class="ending-closing"><div class="ending-village" aria-label="Your woodland village at the end of the investigation">${villageMarkup(state,{interactive:false})}</div><div class="ending-copy"><h2>The truth brought to light.</h2><p class="ending-lead">Poppy and Willow helped bring everyone home. They uncovered the timber Bram had removed from the crossing, too. His help during the rescue did not erase his responsibility.</p><p>The baker has left Poppy and Willow a small parcel, with a sealed envelope tucked inside.</p><div class="button-row ending-primary">${button('endingEnvelope','Open the final envelope →')}${button('endingVillage','Visit your village','secondary')}</div></div></div><div class="ending-case-notes"><h2>How the clues came together</h2><div class="rescue-timeline"><button class="rescue-event active" data-rescue="0" aria-pressed="true">${tokenArt('lantern')}<span>The contradiction</span></button><button class="rescue-event" data-rescue="1" aria-pressed="false">${tokenArt('bell')}<span>The evidence</span></button><button class="rescue-event" data-rescue="2" aria-pressed="false">${tokenArt('map')}<span>The responsibility</span></button></div><div id="rescueExplanation" class="rescue-explanation" role="status">Bram denied visiting the crossing that afternoon. The mender remembered speaking to him there, where he had told her he was working underneath.</div><p class="ending-quote">A suspicion starts a question. Evidence supports an answer.</p></div><div class="ending-extras"><div class="ending-stats"><span>6 chapters explored</span><span>${found.length} / ${EGGS.length} woodland secrets</span><span>Your progress is saved</span></div><div class="button-row">${button('endingSecrets','Woodland discoveries','secondary')}${button('endingMemory','Learning progress','secondary')}${button('endingRestart','Play again','text-button restart-link')}</div></div></section>`;
 const scenes=[
 'Bram denied visiting the crossing that afternoon. The mender remembered speaking to him there, where he had told her he was working underneath.',
 'Marked bridge timber lay in the mill. Saw marks on the remaining brace showed deliberate cutting that the storm could not explain.',
 'Bram admitted selling timber and concealing the damage. The village appointed a new caretaker, and Bram had to help pay for repairs.'
 ];
 app.querySelectorAll('[data-rescue]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.rescue);document.querySelector('#rescueExplanation').textContent=scenes[index];app.querySelectorAll('[data-rescue]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});say(scenes[index]);});
 document.querySelector('#endingEnvelope').onclick=async()=>{if(state.story<30||state.pendingReward!=null||screen!=='ending')return;const {endingSecret}=await import('./ending-secret.js?v=20261022-character-names1');if(state.story<30||state.pendingReward!=null||screen!=='ending')return;showModal(endingSecret());};
 document.querySelector('#endingRestart').onclick=requestRestart;document.querySelector('#endingVillage').onclick=village;document.querySelector('#endingSecrets').onclick=journal;document.querySelector('#endingMemory').onclick=()=>showModal('<h2>Your growing skills</h2>'+skills()+'<p>Return to the village to see any memory trails that are ready. Your mystery ending stays unlocked.</p>');
presentMenuView('ending');}
function requestRestart(){
 showModal(`<span class="eyebrow">A fresh investigation</span><h2 class="restart-heading">Restart from chapter one?</h2><p>This clears this browser’s current game progress, village, beacon sparks, woodland secrets and review schedule. You will begin the latest question bank from the start.</p><div class="button-row restart-actions">${button('cancelRestart','Keep playing')}${button('confirmRestart','Yes, restart game','secondary restart-confirm')}</div>`);
 const body=document.querySelector('#modalBody');body.querySelector('#cancelRestart').onclick=()=>modal.close();
 body.querySelector('#confirmRestart').onclick=()=>{state=fresh();void music.reset();selected=-1;feedback=null;solved=false;lastResult=null;save();modal.close();home();say('New investigation started. Your game has restarted at chapter one.');document.querySelector('#play')?.focus();};
 body.querySelector('#cancelRestart').focus();
}
function showModal(html,{paginate=true}={}){document.querySelector('#modalBody').innerHTML=html;if(!modal.open)modal.showModal();if(paginate)paginateModal();}
function how(){showModal('<span class="eyebrow">Meet Poppy</span><h2>A small adventure, at your pace.</h2><p>Poppy needs to bring supplies home. Each crossing is a sentence puzzle. Scout the whole sentence first. Tap a comma only if it needs attention, then fit a piece. Or send Poppy across without changing anything if the route already works. An independent solve earns a permanent spark; three light a beacon. Read the case-note brief before editing. A grammatical repair that misses the brief receives a neutral reminder.</p><p>Need help? Try each side alone. A clue or retry never costs your supplies. Only a structure that needed support returns in a different example, after intervening questions or a later visit.</p><p>Chapter 1 also has three short notebook stops: edit one incorrect word, interpret a phrase in context, and support a detective conclusion with evidence. You can choose a lead and ask for clues without losing supplies. These stops do not replace the sentence-editing trail.</p><p>Open the Clue notebook at any time to connect observations, test a working idea and save your reasoning. Notebook links are optional and never change grammar scores or supplies.</p><p>Finish an expedition to restore a place in the village and choose its decoration. There is no timer and no game over.</p>');}
function guide(){showModal(`<span class="eyebrow">Keep this in your pocket</span><h2>The sentence field guide</h2><p><b>A comma splice joins two complete clauses with only a comma.</b> “The rain stopped, we went out.”</p><p><b>Separate:</b> The rain stopped. We went out.<br><b>Join:</b> The rain stopped, so we went out.<br><b>Link closely related clauses:</b> The rain stopped; we went out.</p><p><b>A dependent opening:</b> Although the rain stopped, the ground stayed wet. “Although the rain stopped” leaves you waiting.</p><p><b>“However” / “therefore”:</b> The rain stopped; however, the ground stayed wet. A comma before “however” is not enough here.</p><p><b>Extra information:</b> The rabbit, who wore a blue scarf, waved. The main clause is “The rabbit waved”.</p><p><b>Use your inner voice:</b> Read each part separately, but check the grammar. A pause is not proof that a comma belongs there.</p><p>Each brief has one target edit. Other grammatical repairs get a neutral reminder about the writing goal. Full stops automatically add capitals. FANBOYS: “for” (reason), “and” (addition), “nor” (second negative), “but” or “yet” (contrast), “or” (alternative), “so” (result). After “nor”, check inversion: “nor had Willow heard it”.</p>${screen==='play'?'<p class="small-note">Opening this guide counts as supported practice for your current crossing.</p>':''}`);if(screen==='play'&&state.activeId&&!solved){state.activeHelp=true;save();}}
const clueNotebook=createClueNotebook({getState:()=>state,save,showModal,announce:say});
const notebookButton=document.querySelector('#notebookBtn');if(notebookButton)notebookButton.onclick=()=>clueNotebook.open();
const journalButton=document.querySelector('#journalBtn');if(journalButton)journalButton.onclick=journal;
document.querySelector('#villageBtn').onclick=()=>{if(screen==='reward')return;village();};document.querySelector('#guideBtn').onclick=guide;document.querySelector('#soundBtn').textContent=sound?'Sound on':'Sound off';document.querySelector('#soundBtn').setAttribute('aria-pressed',String(sound));document.querySelector('#soundBtn').setAttribute('title','Background music: '+MUSIC.title);document.querySelector('#soundBtn').onclick=async ev=>{sound=!sound;ev.currentTarget.textContent=sound?'Sound on':'Sound off';ev.currentTarget.setAttribute('aria-pressed',String(sound));try{localStorage.setItem(KEY+'-sound',String(sound));}catch{}pageSound.setEnabled(sound);frogSound.setEnabled(sound);await music.setEnabled(sound);};document.querySelector('#closeModal').onclick=()=>{modal.close();music.setMood(['story','play','casework'].includes(screen)&&!state.reviewRun&&!state.bonus?chapterMusicMood(BANK.find(q=>q.id===state.activeId)):'calm');};document.querySelector('#saveBtn').onclick=()=>{showModal(`<h2>Your progress</h2><p>${storageOK?'Your latest progress is saved in this browser. Use the same browser and device to continue. Clearing site data removes this save.':'Browser storage is unavailable. This session will not reliably survive closing the page.'}</p><p>${state.seq} crossings completed · ${state.decorations.length} places restored.</p><div class="button-row">${button('restartFromSave','Restart game','secondary')}</div>`);document.querySelector('#modalBody').querySelector('#restartFromSave').onclick=requestRestart;};
// Restoring a solved screen as practice is deliberate: unsubmitted success is never awarded twice.
function startView(){if(state.pendingReward!=null)reward(state.pendingReward);else if(state.story>=30&&!state.endingSeen&&!state.reviewRun&&!state.bonus&&!state.activeId)ending();else home();}
// Measure the first pages with the final font metrics, without a later page reset.
if(document.fonts?.load)Promise.all([400,600,700].map(weight=>document.fonts.load(weight+' 14px "Nunito Sans"'))).then(startView,startView);else startView();

let layoutResize;window.addEventListener?.('resize',()=>{if(document.activeElement?.id==='caseCorrection')return;clearTimeout(layoutResize);layoutResize=setTimeout(()=>{const q=BANK.find(q=>q.id===state.activeId);if(screen==='story'&&q)showStory(q);else if(screen==='play'&&q)draw();else if(screen==='casework'&&q&&activeCasework)showCasework(q,activeCasework);else if(screen==='home')home();else if(screen==='lesson')lesson(chapter(state));else if(screen==='reward')reward(state.pendingReward);else if(screen==='village')village();else if(screen==='ending')ending();},120);});
